R=[['拉丁 haerēre，相关词干 haes-','黏住、贴住、停在原处']]
AD=R+[['拉丁 ad- + haerēre → adhaerēre','贴到、依附于']]
CO=R+[['拉丁 co- + haerēre → cohaerēre','黏在一起；相互连贯']]
CT=CO+[['拉丁 cohaerēns → 法语 cohérent → 英语 coherent','连贯一致的']]
CE=CO+[['拉丁 cohaerentia → 法语 cohérence → 英语 coherence','连在一起的性质；条理一致']]
CS=CO+[['拉丁分词词干 cohaes- + 英语 -ive → cohesive','能结合成整体的']]
IH=R+[['拉丁 in- + haerēre → inhaerēre / inhaerēns','黏在里面、紧密相连'],['英语 inherent','本身固有的、内在的']]
